<template>
	<div class="Login page">
		<!-- 		<div class="box" @focusout="focusout" @focusin="focusin">
			<div class="cell">
				<img class="logo" src="@/assets/img/logo.png" />
			</div> -->
			<!-- :style="{'display':showForm==1?'none':null}" -->
		<div class="box" @focusout="focusout" @focusin="focusin" v-show="showForm!=1||!loginWithoutAccountLocal||loginWithoutAccountLocal">
			<div class="cell padding-10 margin-bottom-10">

				<img class="logo" src="@/assets/img/logo-red.png" />

			</div>
			<div class="cell">
				<div class="input bottom-line code-box" ref="input">
					<img class="icon pre-icon" src="@/assets/img/number.png" />
					<input type="tel" pattern="[0-9]*" v-model="username" name="username" readonly @click="focusin"
						placeholder="请输入手机号码" />
					<img class="icon input-focus" :style="{opacity:(username.length>0?1:0)}"
						@click="clearInput('username')" src="@/assets/img/close.png" />
					<img class="icon end-icon transition-all" :class="historyNumberShow?'':'row-down'"
						@click="historyNumberShow=!historyNumberShow" src="@/assets/img/row-up.png" />
				</div>
				<div class="history-list" v-show="historyNumberShow" :style="{'width':cellWidth+'px'}">
					<div class="history-item" v-for="(item,index) in userHistory" @click="setHistory(item)"
						:key="index">
						{{item.loginName}}
					</div>
					<!-- <div class="history-item" v-show="userHistory.length<=0">暂无</div> -->
				</div>
			</div>

			<div class="cell">
				<div class="input bottom-line code-box">
					<img class="icon pre-icon" src="@/assets/img/lock.png" />
					<input class="" v-model="password" :placeholder="passwordPlaceHolder" name="password" readonly
						@click="focusin" :type="passwordType" />
					<img class="icon input-focus" :style="{opacity:(password.length>0?1:0)}"
						@click="clearInput('password')" src="@/assets/img/close.png" />
					<img class="icon end-icon" v-show="passwordType=='password'" @click="passwordType='text'"
						src="@/assets/img/unview.png" />
					<img class="icon end-icon" v-show="passwordType!='password'" @click="passwordType='password'"
						src="@/assets/img/view.png" />
				</div>
			</div>


			<div class="cell">
				<div class="col-16 forgot text-left font-color-grey">
					<!-- <div v-show="isShowGuest" @click="guestLogin()">{{$t(`login.GuestLogin`)}}</div> -->
				</div>
				<div class="col-8 forgot text-right font-color-grey">
					<div @click="go('/forget')">忘记密码</div>
				</div>
			</div>
			<div class="btn-box">
				<div class="col-24 padding-6">
					<div class="btn bg-red btn-primary color-white" @click="submit">登录</div>
				</div>
				<div class="col-12 padding-6" v-show="isShowGuest">
					<div class="btn btn-grey border-red font-color-red" @click="guestLogin">一键登录</div>
				</div>

				<div class="padding-6" :class="isShowGuest?'col-12':'col-24'">
					<div class="btn btn-grey border-red font-color-red" @click="go('/register')">注册
					</div>
				</div>
			</div>
			<div class="cell">
				<img @click.stop="clickCheck" v-show="checked" class="check" src="@/assets/img/check-red.png" />
				<img @click.stop="clickCheck" v-show="!checked" class="check" src="@/assets/img/uncheck-red.png" />
				<span>&nbsp;&nbsp;</span><span class="text-left check-text">同意并接受《<a class="font-color-red"
						@click.stop="go('/agreement/licenseServiceAgreement')">游戏许可及服务协议</a>》</span>
			</div>
			<div class="icon-box">
				<div class="col-24 font-color-grey" v-show="isShowThirdLogin||(!isIOS&&isShowTaptap)">
					第三方登录
				</div>
				<div v-show="!isIOS&&isShowTaptap" class="col-24 padding-8">
					<img src="@/assets/img/taptap.png" @click="postLogin('taptapLogin')" />
				</div>
				<div v-show="isShowThirdLogin&&(!isIOS||(isQQAppInstalled&&isIOS))" class="padding-8" :class="ios13?'col-8':'col-12'">
					<img src="@/assets/img/qq.png" @click="postLogin('qqLogin')" />
				</div>
				<div v-show="isShowThirdLogin&&(!isIOS||(isWXAppInstalled&&isIOS))" class="padding-8" :class="ios13?'col-8':'col-12'">
					<img src="@/assets/img/wx.png" @click="postLogin('wxLogin')" />
				</div>
				<div v-show="isShowThirdLogin&&ios13" class="col-8 padding-8">
					<img src="@/assets/img/apple.png" @click="postLogin('appleLogin')" />
				</div>
			</div>
			<div class="cell" v-show="!isShowThirdLogin">
			</div>

		</div>
	</div>
</template>

<script>
	import {
		ref
	} from 'vue'
	export default {
		name: 'Login',
		setup() {
			return {
				username: ref(''),
				password: ref(''),
				loginType: ref(null),
				passwordType: ref('password'),
				historyNumberShow: ref(false),
				cellWidth: ref(0),
				checked: ref(false),
				clickTime: ref(Date.now()),
				loading: ref(false),
				showForm: ref(null),
			}
		},
		mounted() {
			console.log(this.ios13)
			this.showForm = this.$route.query.showForm
			if(this.loginWithoutAccount && this.showForm==1 &&this.loginWithoutAccountLocal){
				this.autoGuestLogin()
				return
			}
			if (this.loginRemember) {
				Object.assign(this, this.loginRemember)
			}

			//获得记住的历史用户名密码
			if (this.userHistory && this.userHistory.length > 0) {
				let item = this.userHistory[this.userHistory.length - 1]
				Object.assign(this, {
					username: item.loginName.slice(3, item.loginName.length),
					password: item.password,
					checked: this.loginRemember.checked
				})
			}
			this.inputFocus()

		},
		computed: {
			userHistory() {
				return this.$store.getters['login/userHistory']
			},
			isQQAppInstalled() {
				if (this.initData) {
					return this.initData.isQQAppInstalled
				}
				return false
			},
			isWXAppInstalled() {
				if (this.initData) {
					return this.initData.isWXAppInstalled
				}
				return false
			},
			isShowGuest() {
				if (this.initData) {
					return this.initData.isShowGuest
				}
				return true
			},
			loginWithoutAccount() {
				if (this.initData) {
					return this.initData.loginWithoutAccount
				}
				return true
			},
			loginWithoutAccountLocal(){
				return this.$store.getters.loginWithoutAccountLocal
			},
			isShowThirdLogin() {
				if (this.$store.getters.initData) {
					return this.$store.getters.initData.isShowThirdLogin
				}
				return false
			},
			isShowTaptap() {
				if (this.$store.getters.initData) {
					return this.$store.getters.initData.isShowTaptap
				}
				return false
			},
			loginRememberString() {
				return JSON.stringify({
					username: this.username,
					password: this.password,
					loginType: this.loginType,
					checked: this.checked,
				})
			},
			loginRemember() {
				return this.$store.getters['loginRemember']
			},
			deviceId() {
				return this.$store.getters.initData.yoFiDeviceId || this.$store.getters.initData.yofiDeviceUUID
			},

		},
		watch: {
			loginRememberString(cv) {
				this.$store.commit('SET_LOGIN_REMBER', JSON.parse(cv))
			},
			historyNumberShow() {
				if (this.$refs.input) {
					this.cellWidth = this.$refs.input.clientWidth
				}

			}
		},
		methods: {
			async setHistory(item) {
				this.username = item.loginName.slice(3, item.loginName.length)
				this.loginName = item.loginName
				this.password = item.password
				this.loginType = item.loginType
				this.historyNumberShow = false
				this.submit()
				// if (!this.checked) {
				// 	return this.$toast.show('请勾选下方协议')
				// }
				// let res = await this.$store.dispatch('login/loginAuto', {
				// 	accessToken: item ? item.accessToken : '',
				// 	loginType: item.loginType,
				// })

				// if (this.$check.ok(res)) {
				// 	this.$toast.hide()
				// 	if (!this.userInfo.isAuthentication) {
				// 		return this.go('/auth')
				// 	}
				// 	if (this.userInfo.isForceBindPhone && !this.userInfo.phone) {
				// 		return this.go('/bind')
				// 	}
				// 	let param = Object.assign({
				// 		loginType: item.loginType
				// 	}, res[0].data.data)
				// 	this.$bridge.postLoginSuccess('loginSuccess', param)
				// } else {
				// 	this.$bridge.postLoginSuccess('loginFailed', res)
				// }
			},
			async guestLogin() {
				if (!this.checked) {
					return this.$toast.show('请勾选下方协议')
				}
				this.autoGuestLogin()
		
			},
			async autoGuestLogin() {
				this.loginType = this.LoginTypeDic['guestLogin']
				if (this.userInfo && this.userInfo.phone && this.userInfo.loginType == this.loginType) {
					return this.$toast.show('已绑定手机，请使用' + this.userInfo.phone + '登录')
				}
				// if (this.userInfo && this.userInfo.accessToken) {
				// 	return this.setHistory(Object.assign({
				// 		loginType: this.loginType
				// 	}, this.userInfo))
				// }
				let loginParam = {
					guestLoginName: this.initData.guestLoginName,
					guestLoginPassword: this.initData.guestLoginPassword,
					guestLoginType: this.initData.guestLoginType
				}
				// let loginParam = null
				// if (this.isIOS) {
				// 	loginParam = {
				// 		guestLoginName: this.initData.guestLoginName,
				// 		guestLoginPassword: this.initData.guestLoginPassword,
				// 		guestLoginType: this.initData.guestLoginType
				// 	}
				// } else {
				// 	loginParam = JSON.parse(this.initData.guestLogin)
				// }
				console.log("loginParam.guestLoginName:" + loginParam.guestLoginName)
				let res = await this.$store.dispatch('login/login', {
					// loginName: (this.userInfo && this.userInfo.loginType == this.loginType && this.userInfo
					// 	.loginName) ? this.userInfo.loginName : '',
					loginName: loginParam.guestLoginName,
					// password: (this.userInfo && this.userInfo.loginType == this.loginType && this.userInfo
					// 	.password) ? this.userInfo.password : '',
					password: loginParam.guestLoginPassword,
					loginType: parseInt(loginParam.guestLoginType)
				})

				if (this.$check.ok(res)) {
					this.$toast.hide()
					if (this.loginWithoutAccount){
						if (this.userInfo.isForceAuthentication && !this.userInfo.isAuthentication) {
							return this.go('/auth')
						}
					} else {
						if (!this.userInfo.isAuthentication) {
							return this.go('/auth')
						}
					}

					if (this.userInfo.isForceBindPhone && !this.userInfo.phone) {
						return this.go('/bind')
					}
					
					//localStorage.removeItem("userInfo")
					let param = Object.assign({
						loginType: this.loginType
					}, res[0].data.data)
					this.$bridge.postLoginSuccess('loginSuccess', param)
				} else {
					this.$bridge.postLoginSuccess('loginFailed', res)
				}
			},
			async submit() {
				if (Date.now() - this.clickTime < 500) {
					return
				}
				this.clickTime = Date.now()
				if (!this.username) {
					return this.$toast.show('手机号不能为空')
				}
				if (!this.password) {
					return this.$toast.show('密码不能为空')
				}
				if (this.password.length < 6 || this.password.length > 20) {
					return this.$toast.show('密码长度需大于6位小于20位')
				}
				if (!this.checked) {
					return this.$toast.show('请勾选下方协议')
				}
				this.loginType = this.LoginTypeDic['phoneLogin']
				this.loading = true
				let res = await this.$store.dispatch('login/login', {
					loginName: '+86' + this.username,
					password: this.password,
					loginType: this.loginType,
				})

				this.loading = false
				if (this.$check.ok(res)) {
					this.$toast.hide()
					if (this.userInfo.isForceAuthentication && !this.userInfo.isAuthentication) {
						return this.go('/auth')
					}
					if (this.userInfo.isForceBindPhone && !this.userInfo.phone) {
						return this.go('/bind')
					}
					this.$bridge.postLoginSuccess('loginSuccess', this.userInfo)
				} else {
					this.clickTime = 0
					this.$bridge.postLoginSuccess('loginFailed', res[0].data.data)
				}
			},
			async postLogin(key) {
				if (!this.checked) {
					return this.$toast.show('请勾选上方方协议')
				}
				let res = await this.$bridge.postLogin(key)

				this.loginType = this.LoginTypeDic[key]
				res = await this.$store.dispatch('login/login', {
					code: res.code,
					identityToken: res.code,
					accessToken: res.accessToken ? res.accessToken : res.code,
					loginName: '',
					password: '',
					loginType: this.loginType,
				})
				if (this.$check.ok(res)) {
					this.$toast.hide()
					let param = Object.assign({
						loginType: this.loginType
					}, res[0].data.data)
					this.$store.commit('SET_USER_INFO', param)

					if (this.userInfo.isForceAuthentication && !this.userInfo.isAuthentication) {
						return this.go('/auth')
					}
					if (this.userInfo.isForceBindPhone && !this.userInfo.phone) {
						return this.go('/bind')
					}

					this.$bridge.postLoginSuccess('loginSuccess', param)
				} else {
					this.$bridge.postLoginSuccess('loginFailed', res[0].data.data)
				}
			},
		},

	}
</script>

<style scoped>
	.Login {
		display: table-cell;
		text-align: center;
		vertical-align: middle;
	}

	.forgot {
		padding-bottom: 0;
	}

	.divide {
		height: 8px;
	}

	.or {
		display: inline-block;
		background: #f4f2f2;
		font-weight: 100;
	}

	.icon-box {
		z-index: 999;
	}

	.row-down {
		transform: rotate(-180deg);
		-ms-transform: rotate(-180deg);
		/* IE 9 */
		-moz-transform: rotate(-180deg);
		/* Firefox */
		-webkit-transform: rotate(-180deg);
		/* Safari 和 Chrome */
		-o-transform: rotate(-180deg);
		/* Opera */
	}

	.history-list {
		position: absolute;
		z-index: 9;
		max-height: 200px;
		overflow-y: scroll;
		box-shadow: 0 2px 12px 0 rgb(0, 0, 0, 0.3);
	}

	.history-item {
		width: 100%;
		padding: 6px 0px;
		width: 100%;
		font-size: 16px;
		background-color: #ffffff;
	}
</style>
